local TeaBlender = {}
local PRODUCTS = {
    common_herbal_tea = { name = "Navadni zeliščni čaj", woodCost = 1, time = 3, cost = 30, happiness = 2, healing = 5, description = "Navadni zeliščni čaj za preproste ljudi." },
    silk_packet_tea = { name = "Svilnata vrečka čaja", woodCost = 1, silkCost = 1, linenCost = 1, time = 5, cost = 90, happiness = 3, healing = 10, prestige = 2, description = "Svilnata vrečka čaja za trgovce." },
    porcelain_jar_tea = { name = "Porcelanasta čajnica", woodCost = 1, glassCost = 1, silkCost = 1, clayCost = 1, time = 8, cost = 240, happiness = 4, healing = 18, prestige = 5, description = "Porcelanasta čajnica za plemiče." },
    silver_caddy_tea = { name = "Srebrna čajna posoda", woodCost = 1, glassCost = 1, silverCost = 1, silkCost = 1, clayCost = 1, time = 12, cost = 580, happiness = 5, healing = 28, prestige = 13, description = "Srebrna čajna posoda za visoke plemiče." },
    gold_trimmed_tea = { name = "Zlatookrasni čaj", woodCost = 1, glassCost = 2, goldCost = 1, silverCost = 1, silkCost = 1, clayCost = 1, jewelCost = 1, time = 16, cost = 1300, happiness = 7, healing = 40, prestige = 25, description = "Zlatookrasni čaj z draguljem za visoko plemstvo." },
    royal_grand_tea = { name = "Kraljevski veliki čaj", woodCost = 2, glassCost = 3, goldCost = 2, silverCost = 2, silkCost = 2, jewelCost = 2, pearlCost = 2, time = 23, cost = 3400, happiness = 12, healing = 65, prestige = 56, description = "Veliki kraljevski čaj z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    tea_cottage = { name = "Čajna koča", cost = { gold = 220, wood = 120, stone = 100, silk = 4, clay = 4 }, upkeep = 5, qualityBonus = 5 },
    blending_loft = { name = "Mešalna podstrešje", cost = { gold = 800, wood = 240, stone = 240, glass = 6, silver = 6 }, upkeep = 18, qualityBonus = 18 },
    master_tea_atelier = { name = "Mojstrski čajni atelje", cost = { gold = 2300, wood = 360, stone = 480, silver = 30, gold = 6 }, upkeep = 52, qualityBonus = 30 },
    royal_tea_palace = { name = "Kraljevska čajna palača", cost = { gold = 9500, wood = 580, stone = 740, gold = 60, jewel = 16 }, upkeep = 190, qualityBonus = 55, prestigeBonus = 50 },
}
TeaBlender.woodStock = 14; TeaBlender.silkStock = 10; TeaBlender.linenStock = 8; TeaBlender.clayStock = 10; TeaBlender.glassStock = 10; TeaBlender.silverStock = 6; TeaBlender.goldStock = 6; TeaBlender.jewelStock = 4; TeaBlender.pearlStock = 4
TeaBlender.productStock = {}; TeaBlender.buildings = {}; TeaBlender.maker = nil; TeaBlender.activeMaking = {}; TeaBlender.totalProducts = 0; TeaBlender.dayTimer = 0
function TeaBlender.init() TeaBlender.woodStock=14; TeaBlender.silkStock=10; TeaBlender.linenStock=8; TeaBlender.clayStock=10; TeaBlender.glassStock=10; TeaBlender.silverStock=6; TeaBlender.goldStock=6; TeaBlender.jewelStock=4; TeaBlender.pearlStock=4; TeaBlender.productStock={}; TeaBlender.buildings={}; TeaBlender.maker=nil; TeaBlender.activeMaking={}; TeaBlender.totalProducts=0; TeaBlender.dayTimer=0; print("[TeaBlender] Royal Tea Blender System initialized (6 products, 4 buildings)") end
function TeaBlender.hireMaker(n,s) s=s or math.random(55,90); local c=460+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; TeaBlender.maker={name=n or ("Čajnar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Čajnar najet: %s (spretnost: %d)",TeaBlender.maker.name,s),"success") end; return true end
function TeaBlender.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function TeaBlender.build(id) local ok,e=TeaBlender.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(TeaBlender.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function TeaBlender.getQualityBonus() local b=0; for _,bd in ipairs(TeaBlender.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function TeaBlender.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and TeaBlender.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.silkCost and TeaBlender.silkStock<(d.silkCost or 0) then return false,"Premalo svile" end; if d.linenCost and TeaBlender.linenStock<(d.linenCost or 0) then return false,"Premalo lanu" end; if d.clayCost and TeaBlender.clayStock<(d.clayCost or 0) then return false,"Premalo gline" end; if d.glassCost and TeaBlender.glassStock<(d.glassCost or 0) then return false,"Premalo stekla" end; if d.silverCost and TeaBlender.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and TeaBlender.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and TeaBlender.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and TeaBlender.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #TeaBlender.buildings==0 then return false,"Potrebna čajna koča" end; if not TeaBlender.maker then return false,"Potreben čajnar" end; return true end
function TeaBlender.make(pt,qty) qty=qty or 1; local ok,e=TeaBlender.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then TeaBlender.woodStock=TeaBlender.woodStock-d.woodCost*qty end; if d.silkCost then TeaBlender.silkStock=TeaBlender.silkStock-d.silkCost*qty end; if d.linenCost then TeaBlender.linenStock=TeaBlender.linenStock-d.linenCost*qty end; if d.clayCost then TeaBlender.clayStock=TeaBlender.clayStock-d.clayCost*qty end; if d.glassCost then TeaBlender.glassStock=TeaBlender.glassStock-d.glassCost*qty end; if d.silverCost then TeaBlender.silverStock=TeaBlender.silverStock-d.silverCost*qty end; if d.goldCost then TeaBlender.goldStock=TeaBlender.goldStock-d.goldCost*qty end; if d.jewelCost then TeaBlender.jewelStock=TeaBlender.jewelStock-d.jewelCost*qty end; if d.pearlCost then TeaBlender.pearlStock=TeaBlender.pearlStock-d.pearlCost*qty end; local t=d.time; if TeaBlender.maker then t=math.max(1,t-math.floor(TeaBlender.maker.skill/13)) end; table.insert(TeaBlender.activeMaking,{id="tea_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,healing=d.healing or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Mešanje: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function TeaBlender.completeMaking(m) local q=1.0+(TeaBlender.getQualityBonus()/100); if TeaBlender.maker then q=q+(TeaBlender.maker.skill/150) end; q=math.min(2.4,q); TeaBlender.productStock[m.productType]=(TeaBlender.productStock[m.productType] or 0)+m.quantity; TeaBlender.totalProducts=TeaBlender.totalProducts+m.quantity; if m.healing>0 and _G.state then _G.state.medicine=(_G.state.medicine or 0)+m.healing end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if TeaBlender.maker then TeaBlender.maker.itemsMade=TeaBlender.maker.itemsMade+m.quantity; if math.random()<0.25 then TeaBlender.maker.skill=math.min(100,TeaBlender.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Čaj pripravljen: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"tea.completed",{productName=m.productName,healing=m.healing,prestige=m.prestige,happiness=m.happiness}) end end
function TeaBlender.update(dt) if not _G.state then return end; TeaBlender.dayTimer=TeaBlender.dayTimer+dt; if TeaBlender.dayTimer>=30 then TeaBlender.dayTimer=0; for i=#TeaBlender.activeMaking,1,-1 do local m=TeaBlender.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then TeaBlender.completeMaking(m); table.remove(TeaBlender.activeMaking,i) end end; local tu=0; for _,bd in ipairs(TeaBlender.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if TeaBlender.maker then tu=tu+12 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function TeaBlender.getStats() return {woodStock=TeaBlender.woodStock,silkStock=TeaBlender.silkStock,linenStock=TeaBlender.linenStock,clayStock=TeaBlender.clayStock,glassStock=TeaBlender.glassStock,silverStock=TeaBlender.silverStock,goldStock=TeaBlender.goldStock,jewelStock=TeaBlender.jewelStock,pearlStock=TeaBlender.pearlStock,productStock=TeaBlender.productStock,numBuildings=#TeaBlender.buildings,hasMaker=TeaBlender.maker~=nil,makerName=TeaBlender.maker and TeaBlender.maker.name or "—",makerSkill=TeaBlender.maker and TeaBlender.maker.skill or 0,activeMaking=#TeaBlender.activeMaking,totalProducts=TeaBlender.totalProducts} end
return TeaBlender
